    $container.empty();

    /* 提取有效键值对，过滤隐藏变量 */
    const entries = Object.entries(obj || {}).filter(([k]) => !k.startsWith('_') && !k.startsWith('$'));

    /* 强制循环 25 次以维持 5x5 结构 */
    for (let i = 0; i < 25; i++) {
      const [key, val] = entries[i] || ["--", "--"];

      /* 处理布尔值、数值与对象的显示格式 */
      let displayVal = val;
      if (typeof val === "boolean") displayVal = val ? "✓" : "✕";
      else if (typeof val === "number") displayVal = val.toFixed(0);
      else if (typeof val === "object" && val !== null) displayVal = "...";

      const $item = $(`
        <div class="matrix-unit">
          <div class="u-label" title="${key}">${key}</div>
          <div class="u-value" title="${displayVal}">${displayVal}</div>
        </div>
      `);
      $container.append($item);
    }
  };

  /* 执行身体监测与着装分析的矩阵填充 */
  fillMatrix($("#m-grid-body"), data.body);
  fillMatrix($("#m-grid-outfit"), data.outfit);
}

