async function init() {
  /* 核心逻辑：确保 MVU 变量系统完全就绪后再进行首次渲染 */
  await waitGlobalInitialized('Mvu');

  const refresh = () => {
    /* 模块化调用：由 Step 5 抓取全量数据，再由 Step 6 执行矩阵渲染 */
    const data = loadVars();
    renderVars(data);
